window.hfAuth={user:null,state:null};
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const d=await r.json();if(!r.ok)throw Error(d.error||'요청을 처리하지 못했습니다.');return d}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let mode='login',setup=false;
let approvalTimer=null,approvalFetching=false,approvalSeen=null;
const gate=document.createElement('div');gate.id='auth-gate';document.body.append(gate);
function showAuth(message=''){
 const signup=mode!=='login';gate.hidden=false;document.querySelector('#root').hidden=true;
 gate.innerHTML=`<section class="auth-card"><p class="auth-brand">HF 인턴 홈페이지</p><h1>${mode==='setup'?'관리자 계정 설정':signup?'인턴 회원가입':'오늘의 퀘스트를 시작하세요'}</h1><p class="muted">${mode==='setup'?'포털을 관리할 본인의 이름·사원번호·비밀번호를 설정하세요.':signup?'본사 인턴 가입 신청 · 관리자 승인 후 이용할 수 있어요.':'사원번호와 비밀번호로 로그인하세요.'}</p><div class="auth-tabs"><button type="button" id="login-tab" class="${!signup?'selected':''}">로그인</button><button type="button" id="register-tab" class="${mode==='register'?'selected':''}">회원가입</button></div><form id="auth-form">${signup?'<label>이름<input class="field" name="name" autocomplete="name" maxlength="40" required></label><label>부서<input class="field" name="department" maxlength="80" placeholder="예: 유동화자산처 MBS부" required></label>':''}<label>사원번호<input class="field" name="employee" autocomplete="username" pattern="[A-Za-z0-9_-]{2,30}" maxlength="30" required></label><label>비밀번호<input class="field" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="10"':''} maxlength="128" required></label>${signup?'<label>비밀번호 확인<input class="field" name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><p class="muted">비밀번호는 10자 이상으로 설정해 주세요.</p>':''}<p id="auth-message" role="status">${safe(message)}</p><button class="primary" style="width:100%">${mode==='setup'?'관리자 계정 만들기':signup?'가입 신청':'로그인'}</button></form>${setup&&mode!=='setup'?'<button type="button" id="setup-tab" class="auth-link">처음 사용하시나요? 관리자 설정</button>':''}<p class="muted" style="margin-top:24px">한국주택금융공사 본사 인턴을 위한 포털</p></section>`;
 document.querySelector('#login-tab').onclick=()=>{mode='login';showAuth()};document.querySelector('#register-tab').onclick=()=>{mode='register';showAuth()};const b=document.querySelector('#setup-tab');if(b)b.onclick=()=>{mode='setup';showAuth()};
 document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));const msg=document.querySelector('#auth-message'),button=f.querySelector('button');if(signup&&d.password!==d.confirm){msg.textContent='비밀번호가 일치하지 않습니다.';return}button.disabled=true;try{const r=await api('/api/'+(mode==='login'?'login':mode==='setup'?'setup':'register'),d);if(mode==='login')await enter(r.user);else{setup=mode==='setup'?false:setup;mode='login';showAuth(r.message)}}catch(err){msg.textContent=err.message}finally{button.disabled=false}};
}
async function enter(user){const d=await api('/api/state');window.hfAuth={user,state:d.state};gate.hidden=true;document.querySelector('#root').hidden=false;if(!window.hfPortalLoaded){const script=document.createElement('script');script.src='activity-ui.js?v=20261006-1';script.onload=()=>{const boards=document.createElement('script');boards.src='boards.js?v=20261006-1';boards.onload=()=>{const portal=document.createElement('script');portal.src='portal.js?v=20261006-1';document.body.append(portal)};document.body.append(boards)};document.body.append(script);window.hfPortalLoaded=true}else window.location.reload();const header=document.querySelector('main header');const tools=document.createElement('div');tools.className='auth-tools';tools.innerHTML=`<button type="button" class="profile-menu-button meal-profile-open" aria-label="${safe(user.name)} · ${safe(user.employee)} 식사 상태 설정" title="이번 주 점심·저녁 상태 설정"><span class="profile-menu-avatar" aria-hidden="true">${safe(user.name.slice(0,1))}</span><span>${safe(user.name)} <small>· ${safe(user.employee)}</small></span><svg aria-hidden="true" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg></button>${user.role==='admin'?'<button id="announcement-open" class="auth-link">전체 공지 관리</button><button id="approval-open" class="auth-link">가입 승인 관리</button>':''}<button type="button" id="logout" class="primary logout-button">로그아웃</button>`;header.append(tools);document.querySelector('#logout').onclick=logout;if(user.role==='admin'){document.querySelector('#announcement-open').onclick=()=>showAnnouncements();document.querySelector('#approval-open').onclick=showAdmin;await refreshApprovalNotice();approvalTimer=setInterval(()=>{if(!document.hidden)refreshApprovalNotice()},15000);}}
async function showAdmin(){try{const d=await api('/api/admin/users');updateApprovalNotice(d.users);let modal=document.querySelector('#admin-modal');if(!modal){modal=document.createElement('dialog');modal.id='admin-modal';document.body.append(modal)}modal.innerHTML=`<h2>가입 승인 관리</h2><p class="muted">본사 인턴 여부와 사원번호를 확인한 뒤 승인하세요. 인턴은 최대 30명까지 승인할 수 있습니다.</p><p id="admin-message" role="status"></p>${d.users.map(u=>`<div class="row"><span>${safe(u.name)} · ${safe(u.employee)}<br><small>부서: ${safe(u.department||'미입력')}<br>${{pending:'승인 대기',approved:'승인 완료',rejected:'거절'}[u.status]}${u.role==='admin'?' · 관리자':''}</small>${u.rejection_reason?`<p class="review-reason">거절 사유: ${safe(u.rejection_reason)}</p>`:''}</span><label class="member-department">부서 설정<input class="field" maxlength="80" value="${safe(u.department)}" placeholder="유동화자산처"><button type="button" class="auth-link" data-department-save="${u.id}">저장</button></label>${u.status==='pending'?`<button class="primary" data-review="${u.id}" data-status="approved">승인</button><label class="review-reason-input">거절 사유<input class="field" maxlength="1000" placeholder="부서나 사원번호를 다시 확인해 주세요"></label><button class="auth-link" data-review="${u.id}" data-status="rejected">거절</button>`:''}</div>`).join('')}<button id="admin-close" class="primary" style="margin-top:20px">닫기</button>`;if(!modal.open)modal.showModal();modal.querySelector('#admin-close').onclick=()=>modal.close();modal.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/admin/review',{id:Number(b.dataset.review),status:b.dataset.status,reason:b.closest('.row').querySelector('.review-reason-input input')?.value||''});await showAdmin()}catch(e){modal.querySelector('#admin-message').textContent=e.message;b.disabled=false}})}catch(e){alert(e.message)}}
(async()=>{try{if(location.protocol==='file:')throw Error('회원가입과 로그인은 서버 주소에서 사용할 수 있습니다. http://127.0.0.1:8765/ 으로 접속해 주세요.');const d=await api('/api/me');setup=d.setup;if(d.user)await enter(d.user);else showAuth()}catch(e){showAuth(e.message);document.querySelector('#auth-form').querySelector('button').disabled=true}})();

async function logout(){
 const button=document.querySelector('#logout');button.disabled=true;button.textContent='로그아웃 중…';
 try{
  if(typeof saving!=='undefined')await saving;
  const response=await fetch('/api/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});
  if(!response.ok&&response.status!==401)throw Error('로그아웃하지 못했습니다. 다시 시도해 주세요.');
  clearInterval(approvalTimer);window.hfAuth={user:null,state:null};
  document.querySelector('#admin-modal')?.close();
  location.replace(location.pathname);
 }catch(error){button.disabled=false;button.textContent='로그아웃';const note=document.querySelector('.notice');if(note)note.textContent=error.message;}
}

function updateApprovalNotice(users){
 const pending=users.filter(u=>u.status==='pending'&&u.role==='intern');const button=document.querySelector('#approval-open');if(!button)return;
 button.innerHTML='가입 승인 관리'+(pending.length?` <span class="approval-badge" aria-hidden="true">${pending.length}</span>`:'');
 button.setAttribute('aria-label',pending.length?`가입 승인 관리, 승인 대기 ${pending.length}명`:'가입 승인 관리, 대기 신청 없음');
 button.classList.toggle('has-pending',pending.length>0);
 let status=document.querySelector('#approval-notification');if(!status){status=document.createElement('p');status.id='approval-notification';status.setAttribute('role','status');status.setAttribute('aria-live','polite');document.querySelector('main header').append(status);}
 const ids=pending.map(u=>u.id);const fresh=approvalSeen!==null&&ids.some(id=>!approvalSeen.includes(id));
 status.hidden=true;status.textContent=pending.length?(fresh?'새 가입 신청이 도착했습니다. ':'')+`승인 대기 ${pending.length}명 · 가입 승인 관리에서 확인해 주세요.`:'';
 approvalSeen=ids;
}
async function refreshApprovalNotice(){
 if(approvalFetching||window.hfAuth.user?.role!=='admin')return;approvalFetching=true;
 try{const d=await api('/api/admin/users');updateApprovalNotice(d.users);}catch(error){const button=document.querySelector('#approval-open');if(button)button.title='가입 신청 확인에 실패했습니다. 버튼을 눌러 다시 확인하세요.';}finally{approvalFetching=false;}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshApprovalNotice()});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-department-save]');if(!b)return;b.disabled=true;try{await api('/api/admin/department',{id:Number(b.dataset.departmentSave),department:b.closest('label').querySelector('input').value});await showAdmin();loadActivity();}catch(error){document.querySelector('#admin-message').textContent=error.message;b.disabled=false;}});
